                ConversionSentence(14, "I will set a digital reminder on my smartphone.", "میں اپنے اسمارٹ فون پر ریمائنڈر الارم لگا لیتا ہوں۔", "Mein apne smartphone par reminder alarm laga leta hoon."),
                ConversionSentence(15, "We need to finalize the quarterly schedule by tomorrow morning.", "ہمیں کل صبح تک سہ ماہی شیڈول کو حتمی شکل دینی ہے۔", "Humein kal subah tak schedule ko hatmi shakal deni hai."),
                ConversionSentence(16, "What is today's date according to the Gregorian calendar?", "عیسوی کیلنڈر کے مطابق آج کیا تاریخ ہے؟", "Gregorian calendar ke mutabiq aaj kya tareekh hai?"),
                ConversionSentence(17, "Today is the twenty-fifth of October.", "آج پچیس اکتوبر ہے۔", "Aaj pachees October hai."),
                ConversionSentence(18, "Which day of the week falls on the first of next month?", "اگلے مہینے کی پہلی تاریخ کو ہفتے کا کون سا دن ہے؟", "Aglay maheenay ki pehli tareekh ko kaun sa din hai?"),
                ConversionSentence(19, "It falls on a Monday.", "اس دن پیر کا دن ہے۔", "Us din peer ka din hai."),
                ConversionSentence(20, "Early morning hours are best for mental focus and clarity.", "صبح کا ابتدائی وقت ذہنی یکسوئی اور ارتکاز کے لیے بہترین ہے۔", "Subah ka ibtedai waqt zehni yaksooyi ke liye behtareen hai."),
                ConversionSentence(21, "Never put off until tomorrow what you can accomplish today.", "جو کام آج ہو سکتا ہے اسے کبھی کل پر مت ٹالیں۔", "Jo kaam aaj ho sakta hai usay kabhi kal par mat taalein."),
                ConversionSentence(22, "Can we wrap up this discussion in the next ten minutes?", "کیا ہم اگلے دس منٹ میں اس گفتگو کو مکمل کر سکتے ہیں؟", "Kya hum aglay das minute mein is guftagu ko mukammal kar saktay hain?"),
                ConversionSentence(23, "I have another urgent appointment right at the top of the hour.", "گھنٹے کے اختتام پر میری ایک اور فوری میٹنگ ہے۔", "Ghantay ke ikhtitam par meri aik aur fauri meeting hai."),
                ConversionSentence(24, "We stayed up working until two o'clock in the night.", "ہم رات گئے دو بجے تک کام کرتے رہے۔", "Hum raat gaye do bajay tak kaam kartay rahay."),
                ConversionSentence(25, "Getting eight hours of restful sleep restores your energy.", "آٹھ گھنٹے کی پرسکون نیند توانائی بحال کرتی ہے۔", "Aath ghantay ki neend tawanaayi bahaal karti hai."),
                ConversionSentence(26, "The train departed on time to the exact second.", "ٹرین عین وقت پر ایک ایک سیکنڈ کی پابندی کے ساتھ روانہ ہوئی۔", "Train ain waqt par rawana hui."),
                ConversionSentence(27, "Please avoid arriving late for official corporate ceremonies.", "سرکاری اور دفتری تقریبات میں تاخیر سے پہنچنے سے گریز کریں۔", "Daftari taqreebaat mein takheer se pohnchnay se bachein."),
                ConversionSentence(28, "How much time is left before the submission portal closes?", "پورٹل بند ہونے میں کتنا وقت باقی ہے؟", "Portal band honay mein kitna waqt baaqi hai?"),
                ConversionSentence(29, "We have only twenty-two minutes remaining.", "ہمارے پاس صرف بائیس منٹ باقی ہیں۔", "Hamaray paas sirf 22 minute baaqi hain."),
                ConversionSentence(30, "Hit the submit button immediately without delay.", "بغیر کسی تاخیر کے فوراً سبمٹ کا بٹن دبائیں۔", "Baghair takheer ke fauran submit ka button dabayein."),
                ConversionSentence(31, "Creating a daily checklist saves hours of wasted effort.", "روزانہ کی فہرست بنانا ضائع ہونے والے گھنٹوں کو بچاتا ہے۔", "Rozana ki checklist banana waqt bachata hai."),
                ConversionSentence(32, "Prioritize tasks based on urgency and long-term value.", "کاموں کو اہمیت اور فوری ضرورت کی بنیاد پر ترتیب دیں۔", "Kaamon ko ahmiyat aur zaroorat ki bunyad par tarteeb dein."),
                ConversionSentence(33, "A delayed flight caused us to miss our connecting bus.", "پرواز میں تاخیر کی وجہ سے ہماری اگلی بس چھوٹ گئی۔", "Parwaz mein takheer ki wajah se agli bus chhoot gayi."),
                ConversionSentence(34, "Fortunately, another bus was departing thirty minutes later.", "خوش قسمتی سے تیس منٹ بعد ایک اور بس روانہ ہو رہی تھی۔", "Khush-qismati se 30 minute baad aik aur bus rawana ho rahi thi."),
                ConversionSentence(35, "What time does the morning sun rise in December?", "دسمبر میں صبح کا سورج کس وقت طلوع ہوتا ہے؟", "December mein subah ka sooraj kis waqt tulu hota hai?"),
                ConversionSentence(36, "Sunrise occurs around 7:05 AM in early winter.", "سردیوں کے آغاز میں طلوعِ آفتاب صبح سات بج کر پانچ منٹ پر ہوتا ہے۔", "Sardiyon mein tulu-e-aftab subah 7:05 par hota hai."),
                ConversionSentence(37, "Can you confirm our dinner reservation for 8:30 PM?", "کیا آپ رات ساڑھے آٹھ بجے کی ڈنر بکنگ کنفرم کر سکتے ہیں؟", "Kya aap raat 8:30 ki dinner booking confirm kar saktay hain?"),
                ConversionSentence(38, "Your table is confirmed and reserved under your name.", "آپ کے نام سے ٹیبل کنفرم اور بک کر دی گئی ہے۔", "Aap ke naam se table confirm aur book kar di gayi hai."),
                ConversionSentence(39, "Managing your calendar prevents overlapping commitments.", "شیڈول کا خیال رکھنا دو کاموں کے ٹکراؤ سے بچاتا ہے۔", "Schedule ka khayal rakhna kaamon ke takrao se bachata hai."),
                ConversionSentence(40, "Take short five-minute breaks after every hour of desk work.", "ہر گھنٹے بعد پانچ منٹ کا چھوٹا وقفہ ضرور لیں۔", "Har ghantay baad 5 minute ka waqfa zaroor lein."),
                ConversionSentence(41, "The deadline for scholarship applications is November 30.", "اسکالرشپ کی درخواستیں جمع کروانے کی آخری تاریخ 30 نومبر ہے۔", "Scholarship application ki aakhri tareekh 30 November hai."),
                ConversionSentence(42, "Late submissions will strictly not be entertained by the committee.", "تاخیر سے جمع کرائی گئی درخواستیں قبول نہیں کی جائیں گی۔", "Takheer se jama ki gayi darkhwastein qabool nahi hon gi."),
                ConversionSentence(43, "Let's synchronize our project timelines on Monday.", "آئیں پیر کے روز پروجیکٹ کے اوقات کو ہم آہنگ کرتے ہیں۔", "Aayein peer ke roz project timelines ko ham-aahang kartay hain."),
                ConversionSentence(44, "Time management is actually self-discipline in practice.", "وقت کا انتظام دراصل اپنے اوپر قابو پانے کا نام ہے۔", "Waqt ka intezam dar-asal khud par qaaboo paanay ka naam hai."),
                ConversionSentence(45, "How many days are left until Eid celebrations?", "عید کی خوشیوں میں کتنے دن باقی رہ گئے ہیں؟", "Eid ki khushiyon mein kitnay din baaqi reh gaye hain?"),
                ConversionSentence(46, "Only three days are left until the crescent moon sighting.", "چاند نظر آنے میں صرف تین دن باقی ہیں۔", "Chand nazar aanay mein sirf teen din baaqi hain."),
                ConversionSentence(47, "Make every single moment of your precious life count.", "اپنی قیمتی زندگی کے ہر ایک لمحے کو بامقصد بنائیں۔", "Apni qeemti zindagi ke har aik lamhay ko ba-maqsad banayein."),
                ConversionSentence(48, "He arrived right on the dot without a second's delay.", "وہ بغیر ایک سیکنڈ کی تاخیر کے بالکل عین وقت پر پہنچا۔", "Woh baghair takheer ke bilkul ain waqt par pohancha."),
                ConversionSentence(49, "Value other people's time as much as you value your own.", "دوسروں کے وقت کی بھی اتنی ہی قدر کریں جتنی اپنی کرتے ہیں۔", "Dosron ke waqt ki bhi utni hi qadr karein jitni apni kartay hain."),
                ConversionSentence(50, "May every hour of your life be filled with purpose and peace!", "اللہ تعالیٰ آپ کی زندگی کے ہر گھنٹے کو خیر و برکت سے بھر دے!", "Allah Ta'ala aap ki zindagi ke har lamhay ko barkat bakhshay!")
            )),

