                ConversionSentence(2, "What identity documents are required for account opening?", "اکاؤنٹ کھولنے کے لیے کن شناختی دستاویزات کی ضرورت ہے؟", "Account kholnay ke liye kin dastawezat ki zaroorat hai?"),
                ConversionSentence(3, "Please provide your original CNIC and proof of income.", "براہ کرم اصل شناختی کارڈ اور آمدنی کا ثبوت فراہم کریں۔", "Barah-e-karam asal CNIC aur aamdani ka saboot dein."),
                ConversionSentence(4, "Where is the nearest automated teller machine (ATM)?", "قریب ترین اے ٹی ایم مشین کہاں واقع ہے؟", "Qareeb tareen ATM machine kahan waqay hai?"),
