                ConversionSentence(7, "I need to transfer twenty thousand rupees to an account in Lahore.", "مجھے لاہور کے ایک اکاؤنٹ میں بیس ہزار روپے ٹرانسفر کرنے ہیں۔", "Mujhe Lahore ke account mein 20 hazar rupay transfer karne hain."),
                ConversionSentence(8, "You can make an instant online transfer using the mobile banking app.", "آپ موبائل بینکنگ ایپ سے فوری آن لائن رقم بھیج سکتے ہیں۔", "Aap mobile app se fauri online raqam bhej saktay hain."),
                ConversionSentence(9, "What is the daily cash withdrawal limit on this Visa card?", "اس ویزا کارڈ پر روزانہ کیش نکالنے کی کیا حد ہے؟", "Is Visa card par rozana cash nikaalnay ki kya hadd hai?"),
