                ConversionSentence(11, "I lost my credit card, please block it immediately.", "میرا کریڈٹ کارڈ گم ہو گیا ہے، اسے فوری بلاک کر دیں۔", "Mera credit card gum ho gaya hai, isay fauran block kar dein."),
                ConversionSentence(12, "Your card has been deactivated to prevent unauthorized transactions.", "کسی بھی غلط استعمال سے بچنے کے لیے کارڈ غیر فعال کر دیا گیا ہے۔", "Ghair qanooni istemal se bachanay ke liye card block kar diya gaya hai."),
                ConversionSentence(13, "A replacement card will be delivered to your address within 5 days.", "نیا کارڈ پانچ دن کے اندر آپ کے پتے پر پہنچا دیا جائے گا۔", "Naya card 5 din ke andar aap ke patay par pohancha diya jaye ga."),
                ConversionSentence(14, "Can I get a printed bank account statement for the past six months?", "کیا مجھے پچھلے چھ ماہ کی بینک اسٹیٹمنٹ پرنٹ مل سکتی ہے؟", "Kya mujhe pichlay 6 maah ki bank statement mil sakti hai?"),
                ConversionSentence(15, "You can download the stamped official PDF directly from the app.", "آپ ایپ سے مہر لگی آفیشل پی ڈی ایف فائل ڈاؤن لوڈ کر سکتے ہیں۔", "Aap app se stamped official PDF download kar saktay hain."),
                ConversionSentence(16, "What is the current foreign exchange rate for US dollars to PKR?", "امریکی ڈالر کا پاکستانی روپے میں موجودہ ریٹ کیا ہے؟", "US Dollar ka Pakistani rupay mein maujooda rate kya hai?"),
                ConversionSentence(17, "One US dollar is currently trading at 278 Pakistani rupees.", "ایک امریکی ڈالر اس وقت 278 پاکستانی روپے پر ہے۔", "Aik US dollar is waqt 278 Pakistani rupay par hai."),
                ConversionSentence(18, "Are there any hidden international transaction fee charges?", "کیا بیرونِ ملک کارڈ کے استعمال پر کوئی پوشیدہ چارجز ہیں؟", "Kya international card istemal par koi hidden charges hain?"),
                ConversionSentence(19, "A standard one percent foreign currency conversion fee applies.", "ایک فیصد فارن کرنسی کنورژن فیس لاگو ہوتی ہے۔", "Aik feesad foreign currency conversion fee laagu hoti hai."),
                ConversionSentence(20, "I would like to deposit a crossed bank pay order cheque.", "میں ایک کراس پے آرڈر چیک جمع کروانا چاہتا ہوں۔", "Mein aik crossed pay order cheque jama karwana chahta hoon."),
                ConversionSentence(21, "Please fill out the deposit slip and write your account number.", "ڈپازٹ سلپ پر کریں اور اپنا اکاؤنٹ نمبر پیچھے درج کریں۔", "Deposit slip bharrein aur apna account number likhein."),
                ConversionSentence(22, "How long does interbank clearing take for outstation cheques?", "دوسرے شہر کے چیک کی کلیئرنگ میں کتنا وقت لگتا ہے؟", "Dosray shehar ke cheque ki clearing mein kitna waqt lagta hai?"),
                ConversionSentence(23, "Outstation cheques clear in two to three business days.", "دوسرے شہر کے چیک دو سے تین کاروباری دنوں میں کلیئر ہوتے ہیں۔", "Outstation cheques 2 se 3 dinon mein clear hotay hain."),
                ConversionSentence(24, "Do you offer Islamic banking profit-and-loss sharing accounts?", "کیا آپ کے پاس اسلامی بینکاری کے نفع و نقصان والے اکاؤنٹس ہیں؟", "Kya aap ke paas Islamic banking accounts hain?"),
                ConversionSentence(25, "Yes, all our Islamic branches comply strictly with Shariah principles.", "جی ہاں، ہماری تمام اسلامی برانچیں شریعت کے اصولوں کے مطابق ہیں۔", "Jee haan, hamari tamam Islamic branches Shariat ke mutabiq hain."),
                ConversionSentence(26, "What is the annual return rate on fixed term deposits?", "مقررہ مدتی فکسڈ ڈپازٹ پر سالانہ منافع کی شرح کیا ہے؟", "Fixed term deposit par salana munafa ki sharah kya hai?"),
                ConversionSentence(27, "Please enable internet banking and online e-commerce transactions.", "براہ کرم انٹرنیٹ بینکنگ اور آن لائن شاپنگ فعال کر دیں۔", "Barah-e-karam internet banking aur online shopping activate karein."),
                ConversionSentence(28, "You will receive a one-time passcode (OTP) on your registered phone.", "آپ کے رجسٹرڈ فون نمبر پر ون ٹائم پاس ورڈ موصول ہوگا۔", "Aap ke registered phone par OTP mosool hoga."),
                ConversionSentence(29, "Never share your banking OTP or password with anyone.", "اپنا بینک او ٹی پی یا پاس ورڈ کبھی کسی سے شیئر نہ کریں۔", "Apna bank OTP ya password kabhi kisi se share na karein."),
                ConversionSentence(30, "Bank officials will never ask for your confidential PIN or OTP.", "بینک عملہ کبھی آپ سے خفیہ پن کوڈ یا او ٹی پی نہیں مانگتا۔", "Bank amla kabhi aap se PIN ya OTP nahi mangta."),
                ConversionSentence(31, "I noticed an unrecognized transaction on my monthly statement.", "مجھے اپنی ماہانہ اسٹیٹمنٹ پر ایک غیر واضح کٹوتی نظر آئی ہے۔", "Mujhe apni monthly statement par ghair-wazeh katoti nazar aayi hai."),
                ConversionSentence(32, "Let us initiate an immediate fraud investigation and dispute.", "ہم فوری طور پر فراڈ کی تفتیش اور کلیم کا عمل شروع کرتے ہیں۔", "Hum fauri fraud investigation aur claim shuru kartay hain."),
                ConversionSentence(33, "Saving a percentage of your monthly income builds financial security.", "ماہانہ آمدنی کا کچھ حصہ بچانا مالی تحفظ پیدا کرتا ہے۔", "Aamdani ka kuch hissa bachana mali tahaffuz deta hai."),
                ConversionSentence(34, "Investing in mutual funds beats annual inflation over time.", "میوچل فنڈز میں سرمایہ کاری مہنگائی کے اثرات سے بچاتی ہے۔", "Mutual funds mein sarmayakari mehngayi se bachati hai."),
                ConversionSentence(35, "Can I link my digital mobile wallet with my bank account?", "کیا میں اپنا ڈیجیٹل والٹ بینک اکاؤنٹ سے لنک کر سکتا ہوں؟", "Kya mein apna digital wallet bank account se link kar sakta hoon?"),
                ConversionSentence(36, "Yes, linking via Raast ID provides instant zero-fee transfers.", "جی ہاں، راست آئی ڈی سے بغیر فیس کے فوری ٹرانسفر ممکن ہے۔", "Jee haan, Raast ID se baghair fees ke instant transfer mumkin hai."),
                ConversionSentence(37, "What is the fee for issuing an official bank draft?", "بینک ڈرافٹ بنوانے کی کیا سرکاری فیس ہے؟", "Bank draft banwanay ki kya sarkari fees hai?"),
                ConversionSentence(38, "The fee is two hundred rupees plus applicable sales tax.", "فیس دو سو روپے بمعہ لاگو سیلز ٹیکس ہے۔", "Fees 200 rupay ba-ma'a tax hai."),
                ConversionSentence(39, "Please sign across the revenue stamp on the voucher.", "واؤچر پر لگے ہوئے ریونیو ٹکٹ کے اوپر دستخط کریں۔", "Voucher par lagay revenue stamp par dastkhat karein."),
                ConversionSentence(40, "My signature did not match, can I sign again carefully?", "میرا دستخط میچ نہیں ہوا، کیا میں دوبارہ احتیاط سے کر لوں؟", "Mera signature match nahi hua, kya mein dobara kar loon?"),
                ConversionSentence(41, "Yes, please sign exactly as on your official national identity card.", "جی ہاں، بالکل ویسا دستخط کریں جیسا آپ کے شناختی کارڈ پر ہے۔", "Jee haan, bilkul waisa sign karein jaisa CNIC par hai."),
                ConversionSentence(42, "How do I update my registered residential mailing address?", "میں اپنا رجسٹرڈ رہائشی پتہ کیسے تبدیل کروا سکتا ہوں؟", "Mein apna registered rehaishi pata kaisay tabdeel karwa sakta hoon?"),
                ConversionSentence(43, "Submit a written request along with a recent utility bill.", "حالیہ یوٹیلٹی بل کی کاپی کے ساتھ تحریری درخواست جمع کروائیں۔", "Utility bill ki copy ke sath tehreeri darkhwast jama karein."),
