                ConversionSentence(4, "I am delighted you enjoyed the meal; cooked with love.", "مجھے خوشی ہے آپ کو کھانا پسند آیا، یہ محبت سے پکایا گیا تھا۔", "Mujhe khushi hai khana pasand aaya, mohabbat se pakaya tha."),
                ConversionSentence(5, "You delivered an outstanding and persuasive presentation.", "آپ نے ایک انتہائی شاندار اور اثر انگیز پریزنٹیشن دی۔", "Aap ne intehai shandar aur asar-angeez presentation di."),
                ConversionSentence(6, "Your deep knowledge and confidence impressed everyone present.", "آپ کے وسیع علم اور اعتماد نے حاضرین کو بہت متاثر کیا۔", "Aap ke wasee ilm aur aitemaad ne sab ko mutasir kiya."),
                ConversionSentence(7, "You have an incredible talent for creative problem solving.", "آپ کے پاس مسائل کو حل کرنے کی لاجواب صلاحیت ہے۔", "Aap ke paas masail hal karne ki la-jawab salahiyat hai."),
                ConversionSentence(8, "I truly admire your calm patience during difficult situations.", "مشکل حالات میں آپ کے صبر اور ٹھہراؤ کی میں دل سے داد دیتا ہوں۔", "Mushkil halaat mein aap ke sabr ki mein daad deta hoon."),
                ConversionSentence(9, "Your generous hospitality made us feel right at home.", "آپ کی شاندار مہمان نوازی نے ہمیں بالکل اپنے گھر کا احساس دیا۔", "Aap ki mehman-nawazi ne bilkul apne ghar ka ehsaas diya."),
                ConversionSentence(10, "We are deeply thankful for having such wonderful friends like you.", "آپ جیسے باوفا اور مخلص دوست پاکر ہم دل سے شکرگزار ہیں۔", "Aap jaise mukhlis dost paa kar hum shukr-guzar hain."),
                ConversionSentence(11, "Your English pronunciation and fluency have improved remarkably.", "آپ کے انگریزی تلفظ اور روانی میں حیرت انگیز بہتری آئی ہے۔", "Aap ke English talaffuz aur rawani mein behtari aayi hai."),
                ConversionSentence(12, "Thank you, practicing daily with AI has helped me immensely.", "شکریہ، روزانہ مشق کرنے نے میری بہت مدد کی ہے۔", "Shukriya, rozana mashq karne ne meri bohat madad ki hai."),
                ConversionSentence(13, "That is a brilliant idea; let's implement it right away.", "یہ ایک زبردست تجویز ہے، آئیں اسے فوراً لاگو کرتے ہیں۔", "Yeh aik zabardast tajweez hai, aayein isay fauran laagu karein."),
                ConversionSentence(14, "Your sharp attention to fine detail made this project flawless.", "آپ کی باریک بینی نے اس پروجیکٹ کو بے عیب بنا دیا۔", "Aap ki bareek-beeni ne project ko be-aib bana diya."),
                ConversionSentence(15, "You have a melodious voice; you should sing more often.", "آپ کی آواز بہت سریلی ہے، آپ کو گانا گانا چاہیے۔", "Aap ki aawaz bohat sureeli hai, aap ko gana chahiye."),
                ConversionSentence(16, "This home decor is so cozy, warm, and tastefully arranged.", "اس گھر کی سجاوٹ بہت خوبصورت، گرمجوش اور سلیقے سے کی گئی ہے۔", "Is ghar ki sajawat bohat khubsurat aur saleeqay se ki gayi hai."),
                ConversionSentence(17, "You have a natural gift for making people feel valued.", "آپ کے پاس لوگوں کو اہمیت کا احساس دلانے کا قدرتی ہنر ہے۔", "Aap ke paas logon ko izzat dainay ka qudrati hunar hai."),
                ConversionSentence(18, "Your work ethic and punctuality set a great example for all.", "آپ کی محنت اور وقت کی پابندی سب کے لیے مشعلِ راہ ہے۔", "Aap ki mehnat aur waqt ki pabandi sab ke liye misaal hai."),
                ConversionSentence(19, "You handled that difficult client dispute with great diplomacy.", "آپ نے اس ناراض کلائنٹ کے مسئلے کو بڑی دانشمندی سے سلجھایا۔", "Aap ne naraz client ke maslay ko daanishmandi se suljhaya."),
                ConversionSentence(20, "Thank you for always lending a helping hand when needed.", "ضرورت کے وقت ہمیشہ مدد کا ہاتھ بڑھانے کا بہت شکریہ۔", "Zaroorat ke waqt madad karne ka bohat shukriya."),
                ConversionSentence(21, "Your smile has a magical way of brightening up the entire room.", "آپ کی مسکراہٹ پورے کمرے کو خوشیوں سے روشن کر دیتی ہے۔", "Aap ki muskurahat pooray kamray ko roshan kar deti hai."),
                ConversionSentence(22, "This handmade embroidery work shows exceptional artistic mastery.", "اس ہاتھ کی کڑھائی میں بے مثال فنکارانہ مہارت جھلکتی ہے۔", "Is dastkari mein be-misaal fann-karana maharat jhalakti hai."),
                ConversionSentence(23, "You write with such clarity, eloquence, and profound depth.", "آپ بہت واضح، فصیح اور گہرے انداز میں لکھتے ہیں۔", "Aap bohat waazeh aur gehray andaaz mein likhtay hain."),
                ConversionSentence(24, "I appreciate your quick response and dedication to our team.", "ہماری ٹیم کے لیے آپ کے فوری جواب اور لگن کی میں قدر کرتا ہوں۔", "Hamari team ke liye aap ke fauri jawab ki mein qadr karta hoon."),
                ConversionSentence(25, "You have raised such polite, well-mannered, and kind children.", "آپ نے بچوں کی بہت ہی بااخلاق اور شائستہ تربیت کی ہے۔", "Aap ne bachon ki bohat ba-akhlaaq tarbiyat ki hai."),
                ConversionSentence(26, "Thank you, good manners are the most valuable inheritance.", "شکریہ، اچھے اخلاق ہی اصل اور سب سے قیمتی وراثت ہیں۔", "Shukriya, achay ikhlaaq hi qeemti virsa hain."),
                ConversionSentence(27, "Your leadership inspired the entire team to surpass all goals.", "آپ کی قیادت نے پوری ٹیم کو تمام اہداف حاصل کرنے کا جذبہ دیا۔", "Aap ki qiyadat ne team ko ahdaaf hasil karne ka jazba diya."),
                ConversionSentence(28, "Success is always the collective fruit of our united effort.", "کامیابی ہمیشہ ہماری متحدہ محنت کا اجتماعی پھل ہوتی ہے۔", "Kamyabi hamesha hamari muttahida mehnat ka phal hai."),
                ConversionSentence(29, "You look very sharp and dashing in that tailored navy suit.", "آپ اس نیلے سوٹ میں بہت باوقار اور پرکشش لگ رہے ہیں۔", "Aap is suit mein bohat ba-waqar aur pur-kashish lag rahay hain."),
                ConversionSentence(30, "The tea you brewed has the perfect balance of cardamom.", "آپ کی بنائی ہوئی چائے میں الائچی کا ذائقہ بالکل پرفیکٹ ہے۔", "Aap ki banayi chai mein elaichi ka zaiqa perfect hai."),
                ConversionSentence(31, "You are a dependable friend I can trust with my eyes closed.", "آپ وہ قابلِ اعتماد دوست ہیں جس پر میں آنکھ بند کر کے بھروسہ کر سکتا ہوں۔", "Aap qabil-e-aitemaad dost hain jis par mein bharosa karta hoon."),
                ConversionSentence(32, "True loyalty in friendship is a precious treasure in this world.", "دوستی میں سچی وفاداری دنیا کا سب سے نایاب خزانہ ہے۔", "Dosti mein sachi wafadari duniya ka anmol khazana hai."),
                ConversionSentence(33, "Your sense of humor always lifts everyone's spirits instantly.", "آپ کا خوش مزاج انداز محفل کی اداسی کو فوراً دور کر دیتا ہے۔", "Aap ka khush-mizaj andaaz mehfil ko khushgawar bana deta hai."),
                ConversionSentence(34, "Laughter is the most effective medicine for everyday fatigue.", "ہنسنا روزمرہ تھکاوٹ کے لیے سب سے مؤثر دوا ہے۔", "Hansna rozmarrah thakawat ke liye mo'assar dawa hai."),
                ConversionSentence(35, "You have designed this user interface with remarkable elegance.", "آپ نے یہ یوزر انٹرفیس انتہائی خوبصورتی اور نفاست سے بنایا ہے۔", "Aap ne yeh UI intehai khubsurti se banaya hai."),
                ConversionSentence(36, "Thank you, user experience was my primary guiding priority.", "شکریہ، صارفین کی سہولت میری اولین ترجیح تھی۔", "Shukriya, users ki sahulat meri pehli tarjeeh thi."),
                ConversionSentence(37, "Your daughter played the piano with astonishing musical skill.", "آپ کی بیٹی نے پیانو پر حیرت انگیز مہارت کا مظاہرہ کیا۔", "Aap ki beti ne piano par shandar maharat dikhayi."),
                ConversionSentence(38, "We encourage her creative passion with love and support.", "ہم محبت اور حوصلہ افزائی کے ساتھ اس کے شوق کو پروان چڑھاتے ہیں۔", "Hum mohabbat ke sath us ke shauq ko barhatay hain."),
                ConversionSentence(39, "You explained that complex concept in such simple terms.", "آپ نے اس پیچیدہ نکتے کو کتنے سادہ اور آسان انداز میں سمجھایا۔", "Aap ne is pecheeda nukte ko kitnay saada andaaz mein samjhaya."),
                ConversionSentence(40, "A great teacher makes difficult concepts easy to comprehend.", "ایک قابل استاد مشکل بات کو بھی فہم کے قریب بنا دیتا ہے۔", "Aik qabil ustaad mushkil baat ko aasan bana deta hai."),
                ConversionSentence(41, "Your honesty and moral integrity are truly exemplary.", "آپ کی دیانت داری اور اخلاقی اصول واقعی قابلِ تقلید ہیں۔", "Aap ki diyanat-dari waqai qabil-e-tareef hai."),
                ConversionSentence(42, "Living with truthfulness brings unshakeable inner peace.", "سچائی کے ساتھ زندگی گزارنا پائیدار دلی سکون دیتا ہے۔", "Sachayi ke sath zindagi guzarna dili sukoon deta hai."),
                ConversionSentence(43, "You organized this grand conference with flawless precision.", "آپ نے اس بڑی کانفرنس کا شاندار اور بے عیب انتظام کیا۔", "Aap ne is conference ka be-aib intezam kiya."),
                ConversionSentence(44, "Thank you to the whole dedicated volunteer organizing committee.", "تمام مخلص رضاکاروں اور انتظامی کمیٹی کا بہت شکریہ۔", "Tamam volunteers aur committee ka bohat shukriya."),
                ConversionSentence(45, "You have a wonderful eye for capturing breathtaking photographs.", "آپ کے پاس لاجواب تصاویر کھینچنے کی کمال کی نظر ہے۔", "Aap ke paas tasweerein khenchnay ki kamaal nazar hai."),
                ConversionSentence(46, "Photography preserves transient moments for generations.", "فوٹوگرافی گزرتے لمحوں کو نسلوں کے لیے محفوظ کر دیتی ہے۔", "Photography guzartay lamhon ko mehfooz kar deti hai."),
                ConversionSentence(47, "Sincere appreciation costs nothing, but enriches human hearts.", "مخلصانہ تعریف پر کچھ خرچ نہیں ہوتا مگر دلوں کو جیت لیتی ہے۔", "Mukhlisana tareef par kuch kharach nahi hota magar dilon ko jeetti hai."),
                ConversionSentence(48, "Always praise good work openly and encourage striving souls.", "اچھے کام کی کھلے دل سے تعریف کریں اور محنتی لوگوں کا حوصلہ بڑھائیں۔", "Achay kaam ki tareef karein aur logon ka hosla barhayein."),
                ConversionSentence(49, "I feel truly blessed and honored to collaborate with you.", "آپ کے ساتھ مل کر کام کرنا میرے لیے باعثِ فخر اور اعزاز ہے۔", "Aap ke sath kaam karna mere liye ba'is-e-fakhr hai."),
                ConversionSentence(50, "May your talents continue to shine bright and inspire millions!", "اللہ تعالیٰ آپ کی صلاحیتوں کو مزید چمکائے اور برکت دے!", "Allah Ta'ala aap ki salahiyaton ko mazeed chamkaye!")
