                ConversionSentence(20, "Certainly, apologies if the loud sound disturbed your sleep.", "یقیناً، معذرت اگر اونچی آواز سے آپ کی نیند میں خلل پڑا۔", "Yaqeenan, ma'zarat agar oonchi aawaz se khalal parra."),
                ConversionSentence(21, "Admitting one's mistake requires true humility and courage.", "اپنی غلطی تسلیم کرنا سچی عاجزی اور بہادری کی نشانی ہے۔", "Apni ghalti tasleem karna sachi aajzi aur bahaduri hai."),
                ConversionSentence(22, "A sincere apology repairs bridges between separated hearts.", "مخلصانہ معافی ٹوٹے ہوئے دلوں کے درمیان پل کا کام کرتی ہے۔", "Mukhlisana maafi tootay dilon ko jorti hai."),
                ConversionSentence(23, "Please excuse my messy desk; I am finishing urgent files.", "بکھری ہوئی میز کے لیے معافی، میں ضروری فائلیں نمٹا رہا ہوں۔", "Bikhri maiz ke liye maafi, mein zaroori files nipta raha hoon."),
                ConversionSentence(24, "Don't worry, a creative mind often works amidst busy files.", "کوئی بات نہیں، تخلیقی ذہن اکثر مصروف فائلوں کے بیچ کام کرتا ہے۔", "Koi baat nahi, busy files ke beech kaam hota hai."),
                ConversionSentence(25, "I forgot to bring the USB flash drive you requested.", "میں وہ یو ایس بی فلیش ڈرائیو لانا بھول گیا جو آپ نے مانگی تھی۔", "Mein USB drive lana bhool gaya jo aap ne maangi thi."),
                ConversionSentence(26, "No problem, you can email me the project zip file instead.", "کوئی مسئلہ نہیں، آپ پروجیکٹ کی فائل ای میل کر دیں۔", "Koi masla nahi, aap project file email kar dein."),
