                ConversionSentence(28, "That is very kind and gracious of you, thank you.", "یہ آپ کی انتہائی مہربانی اور حسنِ اخلاق ہے، شکریہ۔", "Yeh aap ki intehai meharbani aur shafqat hai, shukriya."),
                ConversionSentence(29, "Excuse me, is this seat reserved for elderly senior citizens?", "معاف کیجیے گا، کیا یہ نشست بزرگ شہریوں کے لیے مخصوص ہے؟", "Maaf kijiye ga, kya yeh seat buzurgo ke liye makhsoos hai?"),
                ConversionSentence(30, "Yes, please offer it to the elderly gentleman standing there.", "جی ہاں، برائے مہربانی وہاں کھڑے بزرگ کو یہ سیٹ پیش کریں۔", "Jee haan, wahan kharray buzurg ko yeh seat pesh karein."),
                ConversionSentence(31, "I am terribly sorry for breaking your ceramic tea cup.", "آپ کا چینی کا کپ ٹوٹنے پر میں بے حد شرمندہ اور معذرت خواہ ہوں۔", "Aap ka cup tootnay par mein be-hadd sharminda hoon."),
                ConversionSentence(32, "Please don't feel bad, it was just an accidental mishap.", "براہ کرم برا مت مانیں، یہ محض ایک اتفاقی حادثہ تھا۔", "Barah-e-karam bura mat maanein, yeh ittifaqi tha."),
                ConversionSentence(33, "Polite words like 'Please' and 'Thank you' sweeten life.", "برائے مہربانی اور شکریہ جیسے شائستہ الفاظ زندگی کو میٹھا بناتے ہیں۔", "Baraye meharbani aur shukriya jaise alfaaz zindagi sanwaartay hain."),
                ConversionSentence(34, "Courtesy costs nothing, but buys everything valuable in society.", "شائستگی پر کچھ خرچ نہیں ہوتا مگر معاشرے میں ہر قیمتی چیز خرید لیتی ہے۔", "Shaistagi par kuch kharach nahi hota magar izzat dilati hai."),
                ConversionSentence(35, "Forgiving others liberates your own heart from toxic burdens.", "دوسروں کو معاف کرنا انسان کے اپنے دل کو بوجھ سے آزاد کرتا ہے۔", "Dosron ko maaf karna dil ko bojh se azaad karta hai."),
                ConversionSentence(36, "I am sorry for sounding harsh; I was under immense pressure.", "تلخ لہجے کے لیے معافی چاہتا ہوں، میں شدید دباؤ میں تھا۔", "Talkh lehjay ke liye maafi chahta hoon, mein dabao mein tha."),
                ConversionSentence(37, "We all have stressful days; let us move past it warmly.", "ہم سب کے ساتھ مشکل دن آتے ہیں، آئیں اسے پیار سے بھلا دیں۔", "Hum sab ke sath mushkil din aatay hain, isay bhula dein."),
                ConversionSentence(38, "Could I please trouble you for directions to the exit gate?", "کیا میں باہر نکلنے کے راستے کے لیے آپ کو زحمت دے سکتا ہوں؟", "Kya mein exit gate ke rastay ke liye aap ko takleef de sakta hoon?"),
                ConversionSentence(39, "It is no trouble at all; turn right at the corner.", "بالکل کوئی زحمت نہیں، کونے سے دائیں مڑ جائیں۔", "Bilkul koi takleef nahi, konay se daayein murr jayein."),
                ConversionSentence(40, "I deeply value our relationship and apologize for the misunderstanding.", "میں ہمارے تعلق کی قدر کرتا ہوں اور غلط فہمی پر معافی مانگتا ہوں۔", "Mein hamaray ta'alluq ki qadr karta hoon aur maafi mangta hoon."),
                ConversionSentence(41, "Mutual respect and forgiveness make bonds unbreakable.", "باہمی عزت اور درگزر رشتوں کو لازوال بنا دیتے ہیں۔", "Baahmi izzat aur darguzar rishton ko la-zawal banatay hain."),
                ConversionSentence(42, "Excuse me, I believe you dropped your leather car key.", "معاف کیجیے گا، شاید آپ کی گاڑی کی چابی نیچے گر گئی ہے۔", "Maaf kijiye ga, shayad aap ki car ki chaabi gir gayi hai."),
                ConversionSentence(43, "Oh thank you so very much, I hadn't even noticed it falling.", "ارے آپ کا بے حد شکریہ، مجھے تو گرنے کا پتہ ہی نہیں چلا۔", "Aray aap ka be-hadd shukriya, mujhe pata hi nahi chala."),
                ConversionSentence(44, "Please accept this small token of apology and goodwill.", "براہ کرم معذرت اور خیر سگالی کا یہ چھوٹا سا تحفہ قبول کریں۔", "Barah-e-karam ma'zarat aur khair-sagali ka yeh tohfa qabool karein."),
                ConversionSentence(45, "Your kind gesture is warmly accepted with open arms.", "آپ کا یہ پیارا جذبہ کھلے دل کے ساتھ قبول کیا جاتا ہے۔", "Aap ka yeh pyara jazba khulay dil se qabool hai."),
                ConversionSentence(46, "Gentleness in speech is the ultimate ornament of character.", "گفتگو میں نرمی انسان کے کردار کا سب سے خوبصورت زیور ہے۔", "Guftagu mein narmi ikhlaaq ka behtareen zewar hai."),
                ConversionSentence(47, "Never hesitate to say sorry whenever you are in the wrong.", "جب بھی آپ غلطی پر ہوں تو معذرت کرنے میں کبھی نہ جھجکیں۔", "Jab bhi aap ghalti par hon maafi maangnay mein mat jhijhkein."),
                ConversionSentence(48, "Treat everyone with the same courtesy you desire for yourself.", "ہر ایک سے وہی شائستہ سلوک کریں جس کی آپ خود تمنا رکھتے ہیں۔", "Har aik se wahi shaista sulook karein jo khud chahtay hain."),
                ConversionSentence(49, "A polite society is built on patience, respect, and mutual pardon.", "ایک مہذب معاشرہ صبر، عزت اور معافی کے ستونوں پر بنتا ہے۔", "Aik mohazzab ma'ashra sabr aur izzat par banta hai."),
                ConversionSentence(50, "May your days be graced with harmony, peace, and mutual love!", "اللہ تعالیٰ آپ کے شب و روز کو امن، محبت اور باہمی سکون سے بھر دے!", "Allah Ta'ala aap ki zindagi ko aman aur mohabbat bakhshay!")
            ))
        )
    }
}
